        .chart-line {
            position: absolute;
            bottom: 40px;
            left: 40px;
            right: 40px;
            height: calc(100% - 60px);
        }

        .chart-axis-y {
            position: absolute;
            left: 0;
            top: 0;
            bottom: 40px;
            width: 40px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            font-family: var(--font-body);
            font-size: clamp(0.5rem, 0.8vw, 0.7rem);
            color: var(--text-secondary);
        }

        .chart-axis-x {
            position: absolute;
            bottom: 0;
            left: 40px;
            right: 0;
            height: 30px;
            display: flex;
            justify-content: space-between;
            font-family: var(--font-body);
            font-size: clamp(0.5rem, 0.8vw, 0.7rem);
            color: var(--text-secondary);
        }

        .chart-legend {
            position: absolute;
            top: 0;
            right: 0;
            display: flex;
            gap: 1rem;
            font-family: var(--font-body);
            font-size: var(--small-size);
