        .legend-dot.mobile { background: #3b82f6; }

        /* SVG Line Paths */
        .line-path {
            fill: none;
            stroke-width: 3;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .line-path.desktop { stroke: var(--accent); }
        .line-path.mobile { stroke: #3b82f6; }

        .line-path.connections { stroke: var(--accent); }
        .line-path.requests { stroke: #3b82f6; }
        .line-path.https { stroke: #22c55e; }

        /* Data points */
        .data-point {
            fill: currentColor;
        }

        /* ===========================================
           STAT CARDS
           =========================================== */
        .stat-card {
            background: var(--bg-secondary);
            border-radius: 8px;
            padding: clamp(1rem, 2vw, 1.5rem);
            text-align: center;
        }

        .stat-card .stat-value {
            font-family: var(--font-display);
            font-weight: 800;
            font-size: clamp(2rem, 5vw, 4rem);
            color: var(--text-primary);
            line-height: 1;
        }

        .stat-card .stat-value.accent { color: var(--accent); }
        .stat-card .stat-value.success { color: #22c55e; }

        .stat-card .stat-label {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.5rem;
        }

        .stat-card .stat-context {
            font-family: var(--font-body);
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: 0.3rem;
        }

        .large-stat {
            font-family: var(--font-display);
            font-weight: 800;
            font-size: clamp(4rem, 12vw, 10rem);
            color: var(--accent);
            line-height: 1;
        }

        .large-stat-label {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: var(--text-secondary);
            margin-top: 0.5rem;
        }

        /* ===========================================
           SPLIT LAYOUTS
           =========================================== */
        .split-container {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            height: 100%;
        }

        .split-container.triple {
            grid-template-columns: 1fr 1fr 1fr;
        }

        @media (max-width: 768px) {
            .split-container,
            .split-container.triple {
                grid-template-columns: 1fr;
            }
        }

        /* ===========================================
           PROTOCOL BARS
           =========================================== */
        .protocol-bar {
            display: flex;
            align-items: center;
            gap: 1rem;
            margin-bottom: 1rem;
        }

        .protocol-bar .bar-label {
            font-family: var(--font-body);
            font-size: var(--small-size);
            font-weight: 600;
            width: 80px;
            flex-shrink: 0;
        }

        .protocol-bar .bar-track {
            flex: 1;
            height: 24px;
            background: var(--bg-secondary);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }

        .protocol-bar .bar-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1s var(--ease-out-expo);
        }

        .protocol-bar .bar-fill.http2 { background: #3b82f6; }
        .protocol-bar .bar-fill.http3 { background: var(--accent); }
        .protocol-bar .bar-fill.https { background: #22c55e; }

        .protocol-bar .bar-value {
            font-family: var(--font-display);
            font-weight: 700;
            font-size: var(--small-size);
            width: 50px;
            text-align: right;
        }

        /* ===========================================
           TAKEAWAY SLIDE
           =========================================== */
        .takeaway-slide {
            background: var(--bg-dark);
            color: var(--text-light);
        }

        .takeaway-slide h2 {
            color: var(--text-light);
        }

        .takeaway-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: clamp(0.75rem, 1.5vh, 1.25rem);
        }

        .takeaway-list li {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: rgba(255, 255, 255, 0.85);
            padding-left: 1.5rem;
            position: relative;
            line-height: 1.5;
        }

        .takeaway-list li::before {
            content: '';
            position: absolute;
            left: 0;
            top: 0.5em;
            width: 8px;
            height: 8px;
            background: var(--accent);
            border-radius: 2px;
        }

        .cta-box {
            margin-top: var(--content-gap);
            background: rgba(255, 51, 0, 0.1);
            border-left: 4px solid var(--accent);
            padding: clamp(0.75rem, 1.5vw, 1rem);
            border-radius: 0 8px 8px 0;
        }

        .cta-box p {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: rgba(255, 255, 255, 0.9);
        }

        /* ===========================================
           RESPONSIVE
           =========================================== */
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
            }
        }

        @media (max-height: 600px) {
            .nav-dots, .decorative { display: none; }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           NAVIGATION DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(0.5rem, 2vw, 1.5rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: rgba(0, 0, 0, 0.2);
            cursor: pointer;
            transition: background 0.3s, transform 0.3s;
        }

        .nav-dot:hover { transform: scale(1.3); }
        .nav-dot.active { background: var(--accent); }

        /* Progress bar */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: var(--accent);
            z-index: 1000;
            width: 0%;
            transition: width 0.3s;
        }
    </style>
</head>
